"""Ordered-dither threshold tables for mtkfb. Bayer only: on this panel it was
the only family that looked right.

All 16x16 (smaller orders are tiled up), values 1..255 -- never 0, never 256.
White is rendered iff threshold + luma >= 256, so a 0 entry would put a black
dot on pure white and a 256 entry a white dot on pure black.

Near-white still dots without a white point: Android's backgrounds are often
#FAFAFA, luma 250, where thresholds 1..5 flip the pixel black. mtkfb snaps
luma >= dither_white to white and luma <= dither_black to black.
"""
import numpy as np

N = 16


def bayer(order):
    """Classic recursive Bayer of the given order, tiled up to 16x16."""
    m = np.array([[0, 2], [3, 1]])
    while m.shape[0] < order:
        m = np.block([[4 * m, 4 * m + 2], [4 * m + 3, 4 * m + 1]])
    reps = N // m.shape[0]
    m = np.tile(m, (reps, reps))
    # ranks 0..order^2-1 -> spread over 1..255
    n = order * order
    return 1 + (m.astype(int) * 255) // n


def bayer_mirrored(order):
    """The 'mirrored' variant: alternate tiles are flipped, which breaks the
    long diagonal runs the plain matrix shows in flat mid-greys."""
    base = bayer(order)[: order, : order]
    tile = np.block([[base, np.fliplr(base)],
                     [np.flipud(base), np.flipud(np.fliplr(base))]])
    reps = N // tile.shape[0] if tile.shape[0] <= N else 1
    out = np.tile(tile, (max(reps, 1), max(reps, 1)))[:N, :N]
    return out


TABLES = [
    ("bayer4",  "4x4 -- coarsest, chunky dots, strongest texture", bayer(4)),
    ("bayer8",  "8x8 -- middle ground",                            bayer(8)),
    ("bayer16", "16x16 -- finest gradation, subtlest texture",     bayer(16)),
    ("bayer8m", "8x8 mirrored -- breaks the diagonal runs",        bayer_mirrored(8)),
    ("bayer16m","16x16 mirrored",                                  bayer_mirrored(16)),
]

print("/* Generated by vendor/tools/gen-dither-tables.py -- do not edit. */")
print("static const unsigned char kdither_tables[][256] = {")
for name, note, t in TABLES:
    t = np.clip(t, 1, 255)
    assert t.shape == (N, N), (name, t.shape)
    assert t.min() >= 1 and t.max() <= 255, (name, t.min(), t.max())
    print("\t{ /* %s: %s */" % (name, note))
    for y in range(N):
        print("\t\t" + ", ".join("%3d" % t[y, x] for x in range(N)) + ",")
    print("\t},")
print("};")
